import React, { useEffect, useRef, useState } from 'react';
import { createChart } from 'lightweight-charts';

const PriceChart = ({ symbol, period = '1d', interval = '1m' }) => {
    const chartContainerRef = useRef(null);
    const [chart, setChart] = useState(null);
    const [series, setSeries] = useState(null);

    useEffect(() => {
        if (!chartContainerRef.current) return;

        const newChart = createChart(chartContainerRef.current, {
            width: chartContainerRef.current.clientWidth,
            height: 400,
            layout: {
                background: { color: '#141b2b' },
                textColor: '#e0e6ed',
            },
            grid: {
                vertLines: { color: '#2a3a5c' },
                horzLines: { color: '#2a3a5c' },
            },
            crosshair: {
                mode: 0,
            },
            timeScale: {
                borderColor: '#2a3a5c',
                timeVisible: true,
                secondsVisible: false,
            },
        });

        const newSeries = newChart.addCandlestickSeries({
            upColor: '#4CAF50',
            downColor: '#dc3545',
            borderVisible: false,
            wickUpColor: '#4CAF50',
            wickDownColor: '#dc3545',
        });

        setChart(newChart);
        setSeries(newSeries);

        fetchData(newSeries);

        const handleResize = () => {
            if (chartContainerRef.current) {
                newChart.resize(
                    chartContainerRef.current.clientWidth,
                    400
                );
            }
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            newChart.remove();
        };
    }, [symbol, period, interval]);

    const fetchData = async (seriesInstance) => {
        try {
            const response = await fetch(
                `http://localhost:5000/api/historical/${symbol}?period=${period}&interval=${interval}`
            );
            const data = await response.json();
            
            if (data && data.length > 0) {
                seriesInstance.setData(data);
            }
        } catch (error) {
            console.error('Error fetching chart data:', error);
        }
    };

    return (
        <div style={{
            background: '#141b2b',
            padding: '15px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c',
            marginBottom: '20px'
        }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <h3 style={{ color: '#e0e6ed' }}>{symbol}</h3>
                <div style={{ display: 'flex', gap: '8px' }}>
                    {['1D', '1W', '1M', '3M', '1Y'].map((p) => (
                        <button
                            key={p}
                            onClick={() => {
                                // Change period - you can implement this
                            }}
                            style={{
                                padding: '4px 12px',
                                background: period === p ? '#4CAF50' : '#1a2332',
                                color: period === p ? 'white' : '#8a9bb5',
                                border: '1px solid #2a3a5c',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                fontSize: '12px'
                            }}
                        >
                            {p}
                        </button>
                    ))}
                </div>
            </div>
            <div ref={chartContainerRef} style={{ width: '100%', height: '400px' }} />
        </div>
    );
};

export default PriceChart;
